    endpoint: "https://testnet.toncenter.com/api/v2/jsonRPC",
})
const keyPair = await mnemonicToPrivateKey(mnemonics)
const secretKey = keyPair.secretKey
// The V4 sender uses workchain 0 (basechain).
const workchain = 0
const deployerWallet = WalletContractV4.create({
    workchain: workchain,
    publicKey: keyPair.publicKey,
})

const deployerWalletContract = client.open(deployerWallet)


// with authType = 'internal'
const internalMsgBody = createWalletTransferV5R1({
    authType: 'internal',
    walletId: (builder) => builder.storeInt(v5WalletId, 32),
    validUntil,
    seqno: v5Seqno,
    privateKey: v5PrivateKey,
    actions,
});

// here we use function from previous section to create V5 wallet message cell
// next, we will send it as internal message using V4 wallet

// address of our V5 wallet contract
const v5WalletAddress = Address.parse('<V5_WALLET_ADDRESS>');

const seqnoForV4Wallet = await deployerWalletContract.getSeqno()

await deployerWalletContract.sendTransfer({
    seqno: seqnoForV4Wallet,
    secretKey,
    messages: [
        internal({
            to: v5WalletAddress,
            value: toNano("0.05"),
            body: internalMsgBody,
        }),
    ],
