Пример для **mainnet и горячего кошелька V4R2**. Если у вас V5 или другой `walletId`, используйте соответствующие параметры кошелька. Зависимости: `@ton/ton`, `@ton/crypto`; TypeScript target — ES2020 или новее.

```ts
import {
  Address,
  beginCell,
  internal,
  SendMode,
  toNano,
  TonClient,
  WalletContractV4,
} from "@ton/ton";
import { mnemonicToPrivateKey } from "@ton/crypto";
import { randomBytes } from "node:crypto";

// Переменные окружения:
// TON_MNEMONIC — мнемоника горячего кошелька
// HOT_WALLET_ADDRESS — его ожидаемый TON-адрес
// USER_ADDRESS — обычный TON-адрес получателя
// TONCENTER_API_KEY — API-ключ Toncenter

function env(name: string): string {
  const value = process.env[name]?.trim();
  if (!value) throw new Error(`Не задана ${name}`);
  return value;
}

// Официальный USDT jetton master в mainnet.
const USDT_MASTER = Address.parse(
  "EQCxE6mUtQJKFnGfaROTKOt1lZbDiiX1kCixRv7Nw2Id_sDs",
);
const AMOUNT = 25_000_000n; // 25 USDT, decimals = 6

async function main() {
  const client = new TonClient({
    endpoint: "https://toncenter.com/api/v2/jsonRPC",
    apiKey: env("TONCENTER_API_KEY"),
  });

  const keys = await mnemonicToPrivateKey(
    env("TON_MNEMONIC").split(/\s+/),
  );
  const hotWallet = client.open(
    WalletContractV4.create({
      workchain: 0,
      publicKey: keys.publicKey,
    }),
  );
  const recipient = Address.parse(env("USER_ADDRESS"));

  if (!hotWallet.address.equals(Address.parse(env("HOT_WALLET_ADDRESS")))) {
    throw new Error("Адрес не совпал: проверьте ключи, версию и walletId");
  }

  // Получаем USDT jetton-wallet именно ОТПРАВИТЕЛЯ.
  const result = await client.runMethod(
    USDT_MASTER,
    "get_wallet_address",
    [{
      type: "slice",
      cell: beginCell().storeAddress(hotWallet.address).endCell(),
    }],
  );
  const senderJettonWallet = result.stack.readAddress();

  const data = await client.runMethod(
    senderJettonWallet,
    "get_wallet_data",
  );
  if (data.stack.readBigNumber() < AMOUNT) {
    throw new Error("Недостаточно USDT");
  }

  const attachedTon = toNano("0.1");
  if (await client.getBalance(hotWallet.address) < attachedTon + toNano("0.01")) {
    throw new Error("Недостаточно TON для отправки и комиссий");
  }

  const queryId = randomBytes(8).readBigUInt64BE();
  const body = beginCell()
    .storeUint(0x0f8a7ea5, 32)       // jetton transfer
    .storeUint(queryId, 64)
    .storeCoins(AMOUNT)
    .storeAddress(recipient)        // новый владелец USDT
    .storeAddress(hotWallet.address) // возврат остатка TON
    .storeBit(0)                    // custom_payload отсутствует
    .storeCoins(1n)                 // 1 nanoton для уведомления
    .storeBit(0)                    // пустой inline forward_payload
    .endCell();

  // Выплаты из этого кошелька выполняйте последовательно.
  const seqno = await hotWallet.getSeqno();

  await hotWallet.sendTransfer({
    seqno,
    secretKey: keys.secretKey,
    timeout: Math.floor(Date.now() / 1000) + 120,
    sendMode: SendMode.PAY_GAS_SEPARATELY | SendMode.IGNORE_ERRORS,
    messages: [
      internal({
        to: senderJettonWallet,
        value: attachedTon,
        bounce: true,
        body,
      }),
    ],
  });

  console.log("Запрос отправлен в RPC", {
    seqno,
    queryId: queryId.toString(),
  });
}

main().catch((error) => {
  console.error(error);
  process.exitCode = 1;
});
```

У USDT **6 decimals**, поэтому `toNano("25")` для суммы жетонов использовать нельзя: получится в 1000 раз больше. Сообщение идёт в USDT-кошелёк отправителя, а адрес пользователя находится внутри payload — согласно [схеме TON](https://docs.ton.org/contracts/standard/tokens/jettons/transfer).

`0.1 TON` — бюджет исполнения, остаток возвращается отправителю. Успешный `sendTransfer()` и рост `seqno` ещё не подтверждают зачисление USDT: проверяйте цепочку транзакций до jetton-кошелька получателя. При таймауте сначала проверьте результат; `queryId` сам по себе не предотвращает повторную выплату.
